<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>江南食府 · 菜单</title>
<style>
  :root{
    --zhu:#9e2b25;
    --zhu-deep:#7c1f1b;
    --jin:#c8a45a;
    --ink:#2b2b2b;
    --mi:#f7f3ea;
    --mi-2:#efe7d6;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  body{
    font-family:"Noto Serif SC","Songti SC","STSong","SimSun",serif;
    background:var(--mi);color:var(--ink);line-height:1.8;
  }
  a{text-decoration:none;color:inherit;}
  .wrap{max-width:1100px;margin:0 auto;padding:0 24px;}

  header{
    background:var(--zhu);color:#fff;position:sticky;top:0;z-index:100;
