  }
  .logo-text{font-size:22px;letter-spacing:6px;font-weight:bold;}
  .logo-sub{font-size:11px;letter-spacing:3px;color:#f3dfae;display:block;}
  nav ul{display:flex;gap:8px;list-style:none;flex-wrap:wrap;}
  nav a{display:block;padding:8px 16px;font-size:15px;letter-spacing:2px;border-radius:4px;transition:background .2s;}
  nav a:hover{background:rgba(255,255,255,.15);}
  nav a.active{background:var(--jin);color:var(--zhu-deep);font-weight:bold;}

  .page-banner{
    background:linear-gradient(150deg,#7c1f1b,#9e2b25);
    color:#fff;text-align:center;padding:64px 0 56px;
  }
  .page-banner .en{color:var(--jin);letter-spacing:6px;font-size:13px;margin-bottom:10px;}
